const $=s=>document.querySelector(s);
let ctx,master,engineReady,morphNode,playing=false,preparing=false,restoring=true;
let buffers=[null,null],analysis=[null,null],names=['',''];
let recorder=null,recordSlot=-1,timer,limit,epoch=0;
const status=t=>$('#status').textContent=t;
const defaults=['Your first mouth sound','Your second mouth sound'];
const hints=['A vowel, a hum, a hiss—make any mouth sound.','Make another mouth sound. Something different.'];
const time=t=>Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');
function controls(){document.querySelectorAll('[data-rec]').forEach(b=>{const i=+b.dataset.rec;b.disabled=restoring||preparing||!!buffers[i]||(recordSlot!==-1&&recordSlot!==i)});document.querySelectorAll('[data-file]').forEach(i=>i.disabled=restoring||preparing||recordSlot!==-1||!!buffers[+i.dataset.file]);$('#play').disabled=restoring||preparing||!buffers.every(Boolean)||recordSlot!==-1;$('#demo').disabled=restoring||preparing||recordSlot!==-1||buffers.some(Boolean)}
function audio(){if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.gain.value=+$('#volume').value/100;master.connect(ctx.destination)}return ctx.resume()}
function wave(i,b){const d=b?.getChannelData(0);let html='';for(let n=0;n<65;n++){let amplitude=.04;if(d){let sum=0,start=Math.floor(n*d.length/65),end=Math.floor((n+1)*d.length/65);for(let k=start;k<end;k+=32)sum+=Math.abs(d[k]);amplitude=sum/Math.max(1,Math.ceil((end-start)/32))}html+=`<i style="height:${Math.max(3,Math.min(65,amplitude*150))}px"></i>`}$('#wave'+i).innerHTML=html}
function stop(){if(morphNode){morphNode.disconnect();morphNode.port.close();morphNode=null}playing=false;$('#play').innerHTML='▶ <span>Play morph</span>'}
function mix(){const t=+$('#mix').value/100,label=t===0?'Sustained A':t===1?'Sustained B':`Morph position · ${Math.round(t*100)}%`;$('#mix-label').textContent=label;$('#mix').setAttribute('aria-valuetext',label);morphNode?.port.postMessage({amount:t});saveSettings()}
// One local pair, retained until Start over. No upload or new recording session.
let dbPromise,storageQueue=Promise.resolve();
function db(){return dbPromise??=new Promise((resolve,reject)=>{const request=indexedDB.open('between-mouth-pair',1);request.onupgradeneeded=()=>request.result.createObjectStore('pair');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function stored(mode,action){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('pair',mode),store=tx.objectStore('pair');let result;action(store,v=>result=v);tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
function enqueue(action){storageQueue=storageQueue.catch(()=>{}).then(action);storageQueue.catch(()=>{$('#storage-note').textContent='Saved in this tab only; browser storage is unavailable.'});return storageQueue}
function saveSlot(i){const b=buffers[i];if(!b)return;const entry={name:names[i],sampleRate:b.sampleRate,channels:Array.from({length:b.numberOfChannels},(_,c)=>b.getChannelData(c).slice()),model:analysis[i]};enqueue(()=>stored('readwrite',s=>s.put(entry,'sound'+i)))}
function saveSettings(){if(restoring)return;const settings={mix:+$('#mix').value,volume:+$('#volume').value};enqueue(()=>stored('readwrite',s=>s.put(settings,'settings')))}
function renderSlot(i){const b=buffers[i];wave(i,b);$('#name'+i).textContent=b?names[i]:defaults[i];$('#time'+i).textContent=b?time(b.duration):'00:00';$('#state'+i).textContent=b?'SAVED':'EMPTY';$('#hint'+i).textContent=b?'Kept until you choose Start over.':hints[i];const button=$(`[data-rec="${i}"]`);button.classList.remove('active');button.innerHTML=b?'✓ Sound saved':'<span>●</span> Record sound';$('#wave'+i).style.removeProperty('--selection');if(analysis[i]){const m=analysis[i],selection=m.selection;$('#hint'+i).textContent=m.voice?`Sustained voice · ${Math.round(m.voice.pitch)} Hz`:'Sustained mouth texture';const l=selection.start/b.duration*100,r=selection.end/b.duration*100;$('#wave'+i).style.setProperty('--selection',`linear-gradient(90deg,transparent ${l}%,#8ca57422 ${l}%,#8ca57422 ${r}%,transparent ${r}%)`)}}
function loaded(i,b,name,token){if(token!==epoch)return;buffers[i]=b;analysis[i]=null;names[i]=name;renderSlot(i);saveSlot(i);controls();status(buffers.every(Boolean)?'Both sounds are saved. Play, pause, and morph as often as you like.':'Sound saved. Record the other mouth sound.')}
async function play(){if(preparing||restoring)return;if(playing){stop();status('Paused. Both mouth sounds are kept.');return}if(!buffers.every(Boolean)||recordSlot!==-1)return;const token=epoch;preparing=true;controls();try{await audio();if(token!==epoch)return;if(!ctx.audioWorklet)throw new Error('Use a current browser with audio processing support.');engineReady??=ctx.audioWorklet.addModule('mouth-worklet.js').catch(e=>{engineReady=null;throw e});await engineReady;const {analyzeMouth}=await import('./mouth-dsp.mjs');for(let i=0;i<2;i++){if(!analysis[i]){status('Preparing your mouth sounds. This only happens once per pair.');await new Promise(r=>setTimeout(r,0));if(token!==epoch)return;const b=buffers[i],pcm=new Float32Array(b.length);for(let c=0;c<b.numberOfChannels;c++){const channel=b.getChannelData(c);for(let k=0;k<pcm.length;k++)pcm[k]+=channel[k]/b.numberOfChannels}const m=analyzeMouth(pcm,b.sampleRate);if(token!==epoch)return;analysis[i]=m;renderSlot(i);saveSlot(i)}}if(token!==epoch)return;morphNode=new AudioWorkletNode(ctx,'mouth-morph',{numberOfInputs:0,numberOfOutputs:1,outputChannelCount:[1],processorOptions:{sounds:analysis,amount:+$('#mix').value/100}});morphNode.onprocessorerror=()=>{stop();status('Audio processing stopped. Your sounds are kept; press Play to retry.')};morphNode.connect(master);playing=true;$('#play').innerHTML='Ⅱ <span>Pause morph</span>';status('Your mouth sounds, sustained. Move the slider to transform them.')}catch(e){if(token===epoch){stop();status(e.message||'Could not prepare these sounds. Please try again.')}}finally{if(token===epoch){preparing=false;controls()}}}
function finish(){if(recorder?.state==='recording')recorder.stop()}
async function record(i){if(restoring||preparing||buffers[i])return;if(recordSlot===i){finish();return}if(recordSlot!==-1)return;stop();if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){status('Microphone recording is unavailable. Upload a mouth-sound recording instead.');return}const token=epoch;recordSlot=i;controls();let stream;try{await audio();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});if(token!==epoch){stream.getTracks().forEach(t=>t.stop());return}const current=new MediaRecorder(stream),chunks=[];recorder=current;current.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};current.onstop=async()=>{stream.getTracks().forEach(t=>t.stop());if(token!==epoch)return;clearInterval(timer);clearTimeout(limit);recorder=null;status('Saving your mouth sound…');try{const bytes=await new Blob(chunks,{type:chunks[0]?.type||'audio/webm'}).arrayBuffer();const b=await ctx.decodeAudioData(bytes);if(token!==epoch)return;recordSlot=-1;loaded(i,b,'Mouth sound '+(i?'B':'A'),token)}catch{if(token===epoch){recordSlot=-1;renderSlot(i);controls();status('Could not read the recording. Please record again.')}}};current.start();const started=Date.now(),button=$(`[data-rec="${i}"]`);button.classList.add('active');button.innerHTML='■ Stop recording';$('#state'+i).textContent='RECORDING';timer=setInterval(()=>$('#time'+i).textContent=time((Date.now()-started)/1000),250);limit=setTimeout(finish,60000);status('Make your mouth sound, then press Stop. The microphone turns off after recording.')}catch(e){stream?.getTracks().forEach(t=>t.stop());if(token===epoch){recordSlot=-1;controls();status(e.name==='NotAllowedError'?'Allow microphone access, or upload your mouth sound.':'Could not access the microphone. Please try again.')}}}
function reset(){epoch++;stop();clearInterval(timer);clearTimeout(limit);const old=recorder;recorder=null;recordSlot=-1;if(old?.state==='recording')old.stop();preparing=false;restoring=false;buffers=[null,null];analysis=[null,null];names=['',''];$('#mix').value=50;$('#volume').value=70;if(master)master.gain.setTargetAtTime(.7,ctx.currentTime,.02);document.querySelectorAll('[data-file]').forEach(i=>i.value='');[0,1].forEach(renderSlot);enqueue(()=>stored('readwrite',s=>s.clear()));mix();controls();status('Everything cleared. Record a new pair of mouth sounds.')}
async function restore(){const token=epoch;try{const entries=await stored('readonly',(s,set)=>{const r=s.getAll(),keys=s.getAllKeys();let values; r.onsuccess=()=>values=r.result;keys.onsuccess=()=>set(Object.fromEntries(keys.result.map((k,i)=>[k,values[i]])))});if(token!==epoch)return;for(let i=0;i<2;i++){const entry=entries['sound'+i];if(!entry)continue;const b=new AudioBuffer({length:entry.channels[0].length,numberOfChannels:entry.channels.length,sampleRate:entry.sampleRate});entry.channels.forEach((data,c)=>b.copyToChannel(data,c));buffers[i]=b;analysis[i]=entry.model;names[i]=entry.name;renderSlot(i)}if(entries.settings){$('#mix').value=entries.settings.mix;$('#volume').value=entries.settings.volume}if(buffers.some(Boolean))status('Your saved mouth sounds are ready. Choose Start over whenever you want a new pair.')}catch{$('#storage-note').textContent='Saved in this tab only; browser storage is unavailable.'}finally{if(token===epoch){restoring=false;controls();mix()}}}
document.querySelectorAll('[data-rec]').forEach(b=>b.onclick=()=>record(+b.dataset.rec));
document.querySelectorAll('[data-file]').forEach(input=>input.onchange=async()=>{const i=+input.dataset.file,file=input.files[0],token=epoch;if(!file||buffers[i]||preparing||recordSlot!==-1)return;preparing=true;controls();try{await audio();const b=await ctx.decodeAudioData(await file.arrayBuffer());loaded(i,b,file.name.replace(/\.[^.]+$/,''),token)}catch{if(token===epoch)status('Could not read that audio file. Try WAV or MP3.')}finally{if(token===epoch){input.value='';preparing=false;controls()}}});
$('#play').onclick=play;$('#reset').onclick=reset;$('#mix').oninput=mix;$('#volume').oninput=()=>{if(master)master.gain.setTargetAtTime(+$('#volume').value/100,ctx.currentTime,.02);saveSettings()};
$('#demo').onclick=async()=>{if(preparing||restoring||recordSlot!==-1||buffers.some(Boolean))return;const token=epoch;preparing=true;controls();try{await audio();if(token!==epoch)return;for(let i=0;i<2;i++){const b=ctx.createBuffer(1,ctx.sampleRate*3,ctx.sampleRate),d=b.getChannelData(0),pitch=145;for(let k=0;k<d.length;k++){const t=k/ctx.sampleRate;if(t<.5||t>2.5)continue;const envelope=Math.min(1,(t-.5)/.15,(2.5-t)/.15);let value=0;for(let h=1;h<=35;h++){const hz=h*pitch,formants=i?[[250,100,1.3],[1000,180,.12],[2200,250,.025]]:[[750,140,1],[1150,180,.8],[2600,220,.4]];let amp=.015/h;for(const [f,w,g]of formants)amp+=g*Math.exp(-.5*((hz-f)/w)**2)/Math.sqrt(h);value+=amp*Math.sin(2*Math.PI*hz*t)}d[k]=value*envelope*.16}loaded(i,b,i?'Closed MM · synthetic demo':'Open AH · synthetic demo',token)}status('Demo mouth sounds saved. Press Play and explore.')}finally{if(token===epoch){preparing=false;controls()}}};
$('#help').onclick=()=>$('#guide').showModal();$('#close').onclick=()=>$('#guide').close();window.addEventListener('pagehide',()=>{finish();stop()});[0,1].forEach(renderSlot);controls();restore();
